<template>
  <NModal :show="true" preset="card" class="v2-notice-editor" title="变更确认" :mask-closable="false" :closable="!busy" :close-on-esc="!busy" @update:show="close">
    <div class="v2-notice-tools"><NSelect v-model:value="filter" :options="filters" aria-label="变更确认状态" /><NInput v-model:value="search" clearable placeholder="搜索名称或楼栋" :input-props="{'aria-label':'搜索变更确认'}" /><NButton :loading="loading" :disabled="busy" @click="load">刷新</NButton></div>
    <NAlert v-if="error" type="error" role="alert" :bordered="false">{{ error }}</NAlert><NAlert v-if="warning" type="warning" :bordered="false">{{ warning }}</NAlert>
    <NSpin :show="loading"><section v-for="item in visible.slice((page-1)*10,page*10)" :key="item.target_record_id" class="v2-change-item">
      <header><div><h3>{{ item.title }}</h3><small>{{ item.building }} · {{ item.target_status }}</small></div><NTag :type="item.state==='confirmed'?'success':'warning'" :bordered="false">{{ stateLabel(item.state) }}</NTag></header>
      <NAlert v-if="item.last_error" type="warning" :bordered="false">{{ item.last_error }}</NAlert>
      <NImageGroup><div class="v2-notice-photos"><figure v-for="photo in item.local_screenshot_items||[]" :key="photo.local_image_id"><NImage v-if="safeImage(photo.preview_url)" :src="photo.preview_url" :alt="photo.file_name||'确认截图'" width="110" /><NButton v-if="photo.target_written" quaternary circle :disabled="busy" aria-label="删除确认截图" @click="remove(item,photo)"><Trash2 :size="15" /></NButton></figure></div></NImageGroup>
      <div class="v2-notice-tools"><label class="v2-change-upload"><ImagePlus :size="16" />{{ pending[item.target_record_id]?.file_name||'选择确认截图' }}<input type="file" accept="image/*" :disabled="busy" aria-label="选择确认截图" @change="stage(item,$event)" /></label><NButton v-if="pending[item.target_record_id]" :loading="busy" @click="upload(item)">上传截图</NButton><NButton type="primary" :disabled="busy||!canConfirm||item.state!=='awaiting_confirmation'" @click="confirm(item)">确认变更</NButton></div>
    </section><NEmpty v-if="!loading&&!visible.length&&!error" description="当前没有符合条件的变更" /></NSpin>
    <template #footer><div class="v2-dialog-actions"><NPagination v-model:page="page" :item-count="visible.length" :page-size="10" simple /><NButton :disabled="busy" data-v2-navigation @click="close">关闭</NButton></div></template>
  </NModal>
</template>
<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,ref,watch} from 'vue';
import {NAlert,NButton,NEmpty,NImage,NImageGroup,NInput,NModal,NPagination,NSelect,NSpin,NTag,useDialog,useMessage} from 'naive-ui';
import {ImagePlus,Trash2} from 'lucide-vue-next';
import {requestJson,requestBinaryJson,type Dict} from './client';
import {registerNavigationGuard} from './navigation';
const props=defineProps<{scope:string;focusId?:string}>(),emit=defineEmits<{close:[];changed:[]}>(),dialog=useDialog(),message=useMessage();
const items=ref<Dict[]>([]),pending=ref<Record<string,Dict>>({}),busy=ref(false),loading=ref(false),error=ref(''),warning=ref(''),canConfirm=ref(false),page=ref(1),filter=ref(props.focusId?'all':'pending'),search=ref('');
const filters=[{value:'pending',label:'待处理'},{value:'missing_screenshot',label:'待上传截图'},{value:'awaiting_confirmation',label:'待确认'},{value:'all',label:'全部未结束'}];
const visible=computed(()=>items.value.filter(i=>(filter.value==='all'||filter.value==='pending'&&i.state!=='confirmed'||filter.value===i.state)&&(!search.value||String(i.title+' '+i.building).includes(search.value))));
const stateLabel=(v:string)=>({missing_screenshot:'待上传截图',awaiting_confirmation:'待确认',confirmed:'已确认'}[v]||v);
const safeImage=(url:unknown)=>/^\/api\/notice-images\/[a-f0-9]{32}$/.test(String(url||''));
const base=(i:Dict)=>'/api/change-confirmations/'+encodeURIComponent(i.target_record_id);
let controller:AbortController|undefined;
async function load(){controller?.abort();controller=new AbortController();const c=controller;loading.value=true;error.value='';try{const value=await requestJson('/api/change-confirmations',{signal:c.signal,cache:'no-store'});if(c.signal.aborted)return;items.value=value.items||[];warning.value=value.warning||'';canConfirm.value=value.can_confirm===true;for(const item of items.value)if((item.local_screenshot_items||[]).some((p:Dict)=>p.target_written&&p.local_image_id===pending.value[item.target_record_id]?.local_image_id))delete pending.value[item.target_record_id];if(props.focusId){const index=visible.value.findIndex(i=>i.target_record_id===props.focusId);if(index>=0)page.value=Math.floor(index/10)+1;}}catch(e){if(!c.signal.aborted)error.value=(e as Error).message;}finally{if(controller===c)loading.value=false;}}
async function stage(item:Dict,event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];input.value='';if(!file||busy.value)return;busy.value=true;error.value='';try{if(!file.type.startsWith('image/')||file.size>8*1024*1024)throw new Error('请选择8MB以内的图片。');pending.value[item.target_record_id]=await requestBinaryJson('/api/notice-attachments?'+new URLSearchParams({scope:props.scope,identity:'change:'+item.target_record_id,target_record_id:item.target_record_id,kind:'ali',file_name:file.name}),file,{headers:{'Content-Type':file.type}});}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function upload(item:Dict){if(busy.value)return;const file=pending.value[item.target_record_id];if(!file?.upload_id)return;busy.value=true;error.value='';try{await requestJson(base(item)+'/screenshot',{method:'POST',body:JSON.stringify({upload_id:file.upload_id,local_image_id:file.local_image_id||''})});delete pending.value[item.target_record_id];emit('changed');await load();}catch(e){error.value=(e as Error).message+'；已保留原图片，请先刷新核验上传结果。';}finally{busy.value=false;}}
function confirm(item:Dict){dialog.warning({title:'确认此变更？',content:item.title,positiveText:'确认变更',negativeText:'返回核对',onPositiveClick:async()=>{busy.value=true;try{await requestJson(base(item)+'/confirm',{method:'POST',body:'{}'});emit('changed');await load();}catch(e){error.value=(e as Error).message;return false;}finally{busy.value=false;}}});}
function remove(item:Dict,photo:Dict){dialog.warning({title:'删除此确认截图？',positiveText:'确认删除',negativeText:'取消',onPositiveClick:async()=>{busy.value=true;try{await requestJson(base(item)+'/screenshot?'+new URLSearchParams({local_image_id:photo.local_image_id||'',file_token:photo.file_token||''}),{method:'DELETE'});emit('changed');await load();}catch(e){error.value=(e as Error).message;return false;}finally{busy.value=false;}}});}
function close(){if(busy.value)return;if(Object.keys(pending.value).length)dialog.warning({title:'截图尚未提交',content:'关闭后，本次选择不会上传到变更记录。',positiveText:'关闭',negativeText:'继续处理',onPositiveClick:()=>emit('close')});else emit('close');}
const stop=registerNavigationGuard((_target,proceed)=>{if(busy.value){message.warning('正在处理变更确认，请等待结果');return false;}if(Object.keys(pending.value).length){dialog.warning({title:'截图尚未提交',positiveText:'离开',negativeText:'继续处理',onPositiveClick:proceed});return false;}return true;});
function unload(event:BeforeUnloadEvent){if(busy.value||Object.keys(pending.value).length){event.preventDefault();event.returnValue='';}}
watch([filter,search],()=>page.value=1);onMounted(()=>{void load();window.addEventListener('beforeunload',unload);});onBeforeUnmount(()=>{controller?.abort();stop();window.removeEventListener('beforeunload',unload);});
</script>
<style>.v2-change-item{padding:18px 0;border-bottom:1px solid var(--v2-border)}.v2-change-item header{display:flex;justify-content:space-between;gap:12px;margin-bottom:12px}.v2-change-item h3{font-size:14px;margin:0 0 6px;overflow-wrap:anywhere}.v2-change-item small{color:var(--v2-muted)}.v2-change-upload{display:flex;gap:6px;align-items:center;position:relative;padding:7px 12px;border:1px solid var(--v2-border);border-radius:6px;overflow:hidden;max-width:300px}.v2-change-upload input{position:absolute;inset:0;opacity:0;cursor:pointer}.v2-notice-editor>.n-card-content>.v2-notice-tools>.n-select{width:160px}.v2-notice-editor>.n-card-content>.v2-notice-tools>.n-input{flex:1;min-width:150px}</style>
